def reduce_if_selected(path,raw):
 if path not in SOURCE_INPUTS:return raw
 pin=hashlib.sha256(raw).hexdigest()
 if pin in HISTORICAL_PINS[path]:return raw
 if pin!=SOURCE_INPUTS[path]:raise ValueError('unknown N05 tooling bytes')
 for added,removed in REPLACEMENTS[path]:
  if raw.count(added)!=1:raise ValueError('N05 exact tooling inverse site changed')
  raw=raw.replace(added,removed,1)
 if hashlib.sha256(raw).hexdigest()!=BASE_PINS[path]:raise ValueError('N05 tooling inverse changed other bytes')
 return raw

def assert_production_cohort(root):
 for name,pin in PRODUCTION_PINS.items():
  p=Path(root)/name
  if p.resolve()!=p or not p.is_file()or hashlib.sha256(p.read_bytes()).hexdigest()!=pin:raise ValueError('unknown or mixed N05 production cohort')
 return set(PRODUCTION_PINS)

def reduce_production(path,raw):
 if path not in PRODUCTION_PINS:return raw
 digest=hashlib.sha256(raw).hexdigest()
 if PREVIOUS_PRODUCTION_PINS[path] is not None and digest==PREVIOUS_PRODUCTION_PINS[path]:return raw
 if digest!=PRODUCTION_PINS[path]:raise ValueError('unreviewed N05 native source')
 if PREVIOUS_PRODUCTION_PINS[path] is None:return None
 for added,removed in PRODUCTION_INVERSES[path]:
  if raw.count(added)!=1:raise ValueError('N05 native inverse site changed')
  raw=raw.replace(added,removed,1)
 if hashlib.sha256(raw).hexdigest()!=PREVIOUS_PRODUCTION_PINS[path]:raise ValueError('N05 inverse changed other native bytes')
 return raw

QUALIFICATION_PINS={'support/governance/project-content-grants-qualification/native.php': '5990cfa0fcaed15ba49659bb145650a06ffa51f51e88d0f39a6f3d67fb4b096b', 'support/governance/project-content-grants-qualification/README.md': '720726c4d4ea4240d06f3d89c9abe82511324b3ca60a3da855eb50dd4f77d696', 'support/governance/project-content-grants-qualification/qualify.py': '8fefd6736c5483407208ab83e7b02d16f4df14087b1230a87dd404e7a94f5cde'}

def historical_inputs(root,baseline,changed,current):
 """Remove only exact reviewed N05 bytes, preserving the original historical guard."""
 import subprocess
 changed=set(changed);current=dict(current)
 selected=any(name in current for name,pin in PREVIOUS_PRODUCTION_PINS.items()if pin is None)
 if selected:
  for name,pin in PRODUCTION_PINS.items():
   if name not in current or hashlib.sha256(current[name]).hexdigest()!=pin:raise ValueError('mixed N05 historical input cohort')
  for name in PRODUCTION_PINS:
   raw=reduce_production(name,current[name])
   if raw is None:current.pop(name);changed.discard(name);continue
   current[name]=raw
   old=subprocess.run(['git','-C',str(root),'show',baseline+':'+name],capture_output=True)
   if old.returncode==0 and old.stdout==raw:changed.discard(name);current.pop(name)
 for name,pin in QUALIFICATION_PINS.items():
  if name not in current:continue
  if hashlib.sha256(current[name]).hexdigest()!=pin:raise ValueError('unreviewed N05 qualification source')
  old=subprocess.run(['git','-C',str(root),'cat-file','-e',baseline+':'+name],capture_output=True)
  if old.returncode==0:raise ValueError('qualification source unexpectedly replaces historical path')
  current.pop(name);changed.discard(name)
 import project_content_grant_ci_source_delta as ci_delta
 return ci_delta.historical_inputs(root,baseline,changed,current)
